// Cross-check of rule 3 (docs/wisp/safety.md) between wisp-ota and the Python port that
// `w18.py install-wisp` runs on the bytes it sends (apps/wisp-recovery/wisp_w18/native.py).
// Both suites expand the same vectors (testing/main-payload-vectors.json, generated by
// apps/wisp-recovery/tests/rule3_vectors.py) and must flag exactly the same guard ids.

import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { describe, it } from 'node:test';
import { fileURLToPath } from 'node:url';
import { checkMainPayload } from './guards.ts';

interface Vector {
  name: string;
  length: number;
  patches: [number, string][];
  failed: string[];
}

// Compiled to out-tsc/test/; the JSON stays in src/testing/.
const VECTORS = join(
  dirname(fileURLToPath(import.meta.url)),
  '../../src/testing/main-payload-vectors.json',
);

function expand(vector: Vector): Uint8Array {
  const out = new Uint8Array(vector.length);
  for (const [at, hex] of vector.patches) {
    out.set(Uint8Array.from(Buffer.from(hex, 'hex')), at);
  }
  return out;
}

describe('rule-3 vectors shared with install-wisp', () => {
  const { vectors } = JSON.parse(readFileSync(VECTORS, 'utf8')) as {
    vectors: Vector[];
  };

  it('cover every main-payload guard, passing and failing', () => {
    const ids = new Set(vectors.flatMap((v) => v.failed));
    for (const id of [
      'preamble-format',
      'load-address',
      'preamble-size',
      'image-size',
      'app-end',
      'protected-regions',
      'sp-vector',
      'reset-vector',
      'preamble-crc',
    ]) {
      assert.ok(ids.has(id), `no vector fails ${id}`);
    }
    assert.ok(vectors.some((v) => v.failed.length === 0));
  });

  for (const vector of vectors) {
    it(`${vector.name}: fails exactly ${vector.failed.join(', ') || 'nothing'}`, () => {
      const results = checkMainPayload(expand(vector));
      const failed = results
        .filter((r) => !r.ok)
        .map((r) => r.id)
        .sort();
      assert.deepEqual(failed, [...vector.failed].sort());
    });
  }
});
